export const evaluationCorpus = [
  ...personal.map((t) => ({ category: "personal", topic: t })),
  ...enterprise.map((t) => ({ category: "enterprise", topic: t })),
  ...code.map((t) => ({ category: "code", topic: t })),
].map(({ category, topic: [slug, title, text, question, alias] }) => ({
  category,
  path: `${category}/${slug}.${category === "code" ? "ts" : "md"}`,
  text:
    category === "code"
      ? `/** ${text} */\nexport function ${title}(input: unknown): unknown {\n  // Evaluation fixture for symbol navigation, not production implementation.\n  return input;\n}\n`
      : `# ${title}\n\n${text}\n`,
  queries: [
    question,
    `Find information about ${alias}.`,
    `${title}: ${question}`,
    `I need the source that explains ${alias}.`,
    `Locate ${title}.`,
  ],
}));
